window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[35]={"id":"035","numero":35,"titre":"Anomalies cycle menstruel - métrorragie","objectifs":[{"id":"35-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome prémenstruel","contenu":"<div class=\"notion-course\"><p>Le <span>syndrome prémenstruel (SPM)</span> est un ensemble de <span class=\"nc-yellow_bg\">manifestations </span><strong><span class=\"nc-yellow_bg\">bénignes</span></strong><span class=\"nc-yellow_bg\"> pouvant intéresser de nombreux appareils</span>, dont le seul point commun est leur <strong><span class=\"nc-yellow_bg\">caractère cyclique</span></strong> : apparition dans les <span><span class=\"nc-red nc-bold\">jours qui précèdent les règles</span></span>, disparition <span class=\"nc-green_bg\">au début ou au cours des menstruations</span>. Ils peuvent parfois être présents plus longtemps au cours du cycle (ex : 1ʳᵉ phase de la périménopause).</p>\n\n      <p><strong>Fréquence</strong> : il s'agit de <em>la gêne fonctionnelle la plus fréquemment signalée par les femmes</em> — <span><span class=\"nc-pink nc-bold\">30 à 40 %</span></span> des femmes en âge de procréer.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span <span=\"\">&gt;3</span> grands signes classiques</h4>\n      <table>\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Mastodynies</span></strong></td>\n            <td><span>Douleurs mammaires</span> isolées, <span class=\"nc-brown_bg\">parfois seins réellement douloureux et tendus à l'examen clinique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Signes abdomino-pelviens</span></strong></td>\n            <td>\n              <strong><span class=\"nc-blue_bg\">Ballonnement abdominal</span></strong> : congestion pelvienne, toujours gênant ;<br>\n              <strong>Troubles du transit</strong> : souvent associés ;<br>\n              <strong>Prise de poids transitoire</strong> : <span>3 à 4 kg maximum</span>, possible.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Signes neuropsychologiques</span></strong></td>\n            <td>\n              <span><span class=\"nc-blue_bg\">Céphalées</span></span>, <span><span class=\"nc-blue_bg\">irritabilité</span></span>, <span><span class=\"nc-blue_bg\">anxiété</span></span>, <span><span class=\"nc-blue_bg\">syndrome dépressif</span></span> — intensité le plus souvent modérée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"nc-red nc-bold\">Trouble dysphorique prémenstruel</span> (DSM-5).</strong> Forme <span>psychiatrique invalidante</span> du SPM : syndromes psychiatriques cycliques invalidants (isolés ou associés aux signes mammaires/abdomino-pelviens) avec <strong>retentissement sur la qualité de vie</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":1},{"id":"35-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie du syndrome prémenstruel","contenu":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> du SPM est <em>mal connue</em>. L'<span><span class=\"nc-yellow_bg\">hyperœstrogénie relative</span></span><span class=\"nc-yellow_bg\"> (et parfois même </span><strong><span class=\"nc-yellow_bg\">absolue</span></strong><span class=\"nc-yellow_bg\">)</span> serait l'élément fondateur, induisant <span <span=\"\">&gt;2</span> grands mécanismes :</p>\n\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Conséquences cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Hyperperméabilité capillaire</span></strong></td>\n            <td>\n              <span>Œdème tissulaire interstitiel</span> dans certains organes :<br>\n              <strong>Seins</strong> : <span><span class=\"nc-yellow_bg\">mastodynies</span></span> ;<br>\n              <strong>Cerveau</strong> : <span><span class=\"nc-blue_bg\">céphalées</span></span>, manifestations neuropsychologiques ;<br>\n              <strong>Viscères abdomino-pelviens</strong> : <span>congestion pelvienne</span>, <span>troubles du transit</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Perturbations de la transmission sérotoninergique</span></strong></td>\n            <td>Participe à la survenue des <span><span class=\"nc-blue_bg\">troubles neuropsychologiques</span></span> (<span class=\"nc-blue_bg\">irritabilité</span>, <span class=\"nc-blue_bg\">syndrome dépressif</span>, <span class=\"nc-red nc-bold\">trouble dysphorique prémenstruel</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> C'est la rationalité du recours aux <span><span class=\"nc-pink nc-bold\">ISRS</span></span> dans les formes neuropsychologiques (effet sur la sérotonine) et aux <span>progestatifs/œstroprogestatifs</span> dans les formes globales (<span>réduction</span> du climat d'hyperœstrogénie relative).\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-3","rang":"B","rubrique":"Étiologies","titre":"Connaître les situations physiologiques ou pathologiques pouvant favoriser la survenue ou l’aggravation d’un syndrome prémenstruel","contenu":"<div class=\"notion-course\"><h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Facteurs favorisants</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitements hormonaux</strong></td>\n            <td>\n              <span><span class=\"nc-pink_bg\">Contraceptifs microprogestatifs</span></span> (voie orale ou implant SC) ;<br>\n              <span><span class=\"nc-pink_bg\">DIU au lévonorgestrel</span></span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Consommations excessives</strong> (mode de vie)</td>\n            <td>\n              <span><span class=\"nc-red nc-bold\">Caféine</span></span>, <span><span class=\"nc-red nc-bold\">nicotine</span></span>, <span><span class=\"nc-red nc-bold\">alcool</span></span>, <span><span class=\"nc-red nc-bold\">sucres rapides</span></span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étapes de la vie génitale où le SPM est plus fréquent</h4>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adolescence</strong></td>\n            <td>Les <em>1ers cycles</em> sont volontiers <span>dysovulatoires</span> → peut favoriser une <strong>hyperœstrogénie relative</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ phase de la périménopause +++</strong></td>\n            <td>\n              Tableau d'<span>« hyperstimulation endogène » des ovaires</span> associant :<br>\n              <strong><span class=\"nc-blue_bg\">Raccourcissement des cycles</span></strong> ;<br>\n              <strong><span class=\"nc-blue_bg\">Règles plus abondantes</span></strong>, voire hémorragiques chez certaines patientes ;<br>\n              <strong><span class=\"nc-blue_bg\">Climat d'hyperœstrogénie relative</span></strong><span class=\"nc-blue_bg\"> et même parfois </span><span><span class=\"nc-blue_bg\">absolue</span></span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition du cycle menstruel normal","contenu":"<div class=\"notion-course\"><p>Le <span>cycle menstruel normal</span> est un cycle ovulatoire dont la durée varie typiquement entre <span>25 et 35 jours</span>, comptés du <strong>1ᵉʳ jour des règles</strong> au 1ᵉʳ jour des règles suivantes. Les <span>menstruations normales</span> durent <span>3 à 6 jours</span> et correspondent à des pertes sanguines <span>&lt; 80 mL</span>. La présence de règles régulières signe le bon fonctionnement de l'<strong><span>axe hypothalamo-hypophyso-ovarien</span></strong> et l'intégrité des voies génitales. Une <span>anomalie du cycle menstruel</span> est <em>très souvent le fait d'un défaut d'ovulation</em> (anovulation ou dysovulation).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Anomalies du cycle — définitions à connaître verbatim</h4>\n      <table>\n        <thead><tr><th>Anomalie</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Aménorrhée</span></strong></td>\n            <td><span>Absence de menstruations</span>, primaire ou secondaire.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Oligospanioménorrhée</span></strong></td>\n            <td>Cycles <span><span class=\"nc-pink nc-bold\">&gt; 45 jours</span></span> avec en général des <strong><span class=\"nc-blue nc-bold\">menstruations de faible abondance</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cycles courts</strong></td>\n            <td>Cycles <span><span class=\"nc-pink nc-bold\">&lt; 25 jours</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cycles longs</strong></td>\n            <td>Cycles <span>entre 35 et 45 jours</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Spottings</span></strong></td>\n            <td>Pertes <strong>fréquentes de <span class=\"nc-blue_bg\">faibles quantités</span></strong><span class=\"nc-blue_bg\"> (gouttes) de sang d'origine génitale</span> (quasi-quotidiennes).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir (définitions Collège CNGOF).</strong> Une <em>aménorrhée primaire</em> = absence de règles après <span>15 ans</span> en présence d'un développement normal des caractères sexuels secondaires (ou à<span> 13 ans</span> en l'absence de tout signe de puberté). Une <em>aménorrhée secondaire</em> = arrêt des cycles <span>&gt; 3 mois</span> chez une femme antérieurement réglée. On parle d'<em>aménorrhée primosecondaire</em> en cas d'un unique épisode menstruel <span>suivi</span> d'une aménorrhée. L'aménorrhée peut être <strong>physiologique</strong> : <span><span class=\"nc-brown_bg\">grossesse</span></span>, allaitement, ménopause.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences cliniques des troubles du cycle","contenu":"<div class=\"notion-course\"><p>Les conséquences cliniques varient selon le type de trouble et son ancienneté. Plusieurs grands axes sont à retenir :</p>\n\n      <table>\n        <thead><tr><th>Axe</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Gêne fonctionnelle</strong></td>\n            <td>\n              <span>Inconfort cyclique</span> (<span class=\"nc-yellow_bg\">mastodynies</span>, ballonnement, <span class=\"nc-blue_bg\">irritabilité</span> — cf SPM) ;<br>\n              <span>Retentissement sur la qualité de vie</span>, professionnel, relationnel ;<br>\n              <strong><span class=\"nc-red nc-bold\">Trouble dysphorique prémenstruel</span></strong> (DSM-5) dans les formes psychiatriques sévères.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fertilité</strong></td>\n            <td>\n              <span>Hypofertilité / infertilité</span> en cas d'anovulation chronique (SOPK, insuffisance ovarienne prématurée, hyperprolactinémie) — motif fréquent de consultation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endomètre</strong></td>\n            <td>\n              <span>Hyperplasie endométriale</span> en cas d'imprégnation œstrogénique non opposée par la progestérone (anovulation prolongée) — risque à terme de <strong>cancer de l'endomètre</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragies</strong></td>\n            <td><span>Ménorragies</span> sévères pouvant entraîner une <span>anémie ferriprive</span> ; spottings désagréables.</td>\n          </tr>\n          <tr>\n            <td><strong>Osseux et cardio-vasculaire</strong></td>\n            <td>Carence œstrogénique prolongée (IOP, aménorrhée hypothalamique sévère) → <span>perte de densité osseuse</span> ± retentissement <span>CV</span> à long terme.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Note de source.</strong> Le Collège CNGOF (5ᵉ éd., 2021) ne consacre pas de section spécifique à cet objectif transversal. La synthèse ci-dessus consolide les conséquences mentionnées au fil des chapitres aménorrhée/IOP (carence œstrogénique → risque osseux) et hémorragies (ménorragies → anémie ferriprive ; anovulation prolongée → hyperplasie endométriale).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 42 — Aménorrhée</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de métrorragies","contenu":"<div class=\"notion-course\"><p>Les <span>métrorragies</span> = saignements d'origine utérine survenant <strong>en dehors des règles</strong>. La démarche étiologique se structure <span>par contexte clinique</span>, car l'arborescence change radicalement selon l'âge et le statut hormonal.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Femme en âge de procréer</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Urgence</span> absolue.</strong> Toute métrorragie chez une femme en âge de procréer impose d'<span>éliminer une <span class=\"nc-brown_bg\">grossesse</span> en 1er</span> (<span>β-hCG plasmatique</span>) et de ne pas méconnaître une <span><span class=\"nc-brown_bg\">grossesse</span> extra-utérine (GEU)</span> tant que la <span><span class=\"nc-brown_bg\">grossesse</span></span> n'a pas été localisée par <span>échographie</span>.\n      </div>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Liées à une <span><span class=\"nc-brown_bg\">grossesse</span></span></strong></td>\n            <td>\n              <span>GEU</span> +++ ; <span>fausse couche spontanée</span> ; <span>môle hydatiforme</span> ;<br>\n              <span><span class=\"nc-brown_bg\">Grossesse</span></span> intra-utérine évolutive avec hémorragie de Hartmann (J20-J25, parfois) ;<br>\n              Pathologies du 2ᵉ-3ᵉ trimestre : <span>placenta praevia</span>, <span>hématome rétroplacentaire</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Organiques utérines/cervicales</strong></td>\n            <td>\n              <span>Polypes endométriaux</span> ou cervicaux ;<br>\n              <span>Fibromes utérins</span> (surtout sous-muqueux) ;<br>\n              <span>Adénomyose</span> ;<br>\n              <span>Endométrite</span> aiguë / chronique, <span>cervicite</span>, <span>IGH</span> ;<br>\n              <span>Cancer du col utérin</span> (à évoquer +++ chez la femme jeune avec métrorragies provoquées post-coïtales) ; cancer de l'endomètre (plus rare avant <span>40 ans</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes / contraception</strong></td>\n            <td>\n              <span>COP</span> mal observée, en début de <span>plaquette</span>, oublis ;<br>\n              <span>Microprogestatifs</span>, <span>implant à l'étonogestrel</span>, <span><span class=\"nc-pink_bg\">DIU au lévonorgestrel</span></span> : <em>spottings fréquents les 1ers mois</em> ;<br>\n              <span>DIU au cuivre</span> : <span class=\"nc-blue_bg\">règles plus abondantes</span> ± spottings ;<br>\n              Contraception d'<span>urgence</span> ; <strong>traitement hormonal substitutif</strong> de la ménopause.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnelles</strong></td>\n            <td><span>Anovulation / dysovulation</span> (SOPK, péri-ménarche, périménopause).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Périménopause</h4>\n      <p>Causes <strong>organiques</strong> les plus fréquentes : <span>fibromes</span>, <span>polypes</span>, <span>adénomyose</span>, <span>hyperplasie endométriale</span> ± atypique, <span>cancer de l'endomètre</span> à dépister. Causes fonctionnelles : dysovulation périménopausique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Femme ménopausée</h4>\n      <div class=\"callout callout-danger\">\n        <strong>Toute métrorragie post-ménopausique = <span>cancer de l'endomètre</span> jusqu'à preuve du contraire.</strong> Bilan obligatoire : <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> endovaginale + hystéroscopie ± <span>biopsie</span> endométriale.\n      </div>\n      <p>Autres causes : <span>atrophie endométriale</span>, polypes, fibromes, cancer du col, sarcomes, THM mal équilibré, causes vaginales (atrophie).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Classification</span> mnémotechnique « PALM-COEIN » (FIGO)</h4>\n      <p>Cadre de référence des saignements utérins anormaux <strong>chez la femme non enceinte en âge de procréer</strong> : les <strong>PALM</strong> sont des causes <span>structurelles</span> (imagerie/<span>histologie</span>), les <strong>COEIN</strong> sont <span>non structurelles</span>.</p>\n      <table>\n        <thead><tr><th>PALM (structurelles)</th><th>COEIN (non structurelles)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>P</strong>olype ;<br>\n              <strong>A</strong>dénomyose ;<br>\n              <strong>L</strong>éiomyome (sous-muqueux et autre) ;<br>\n              <strong>M</strong>alignité et hyperplasie.\n            </td>\n            <td>\n              <strong>C</strong>oagulopathie ;<br>\n              <strong>O</strong>vulatoire (dysfonction) ;<br>\n              <strong>E</strong>ndométriale (cause) ;<br>\n              <strong>I</strong>atrogénie ;<br>\n              <strong>N</strong>on autrement précisée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Métrorragies fonctionnelles (diagnostic d'élimination)</h4>\n      <p>Une fois <strong>toutes les étiologies organiques éliminées</strong> :</p>\n      <ul>\n        <li><span>Métrorragies intermenstruelles au 14ᵉ jour</span> du cycle (ovulation) ;</li>\n        <li><span>Métrorragies prémenstruelles</span> par insuffisance lutéale ;</li>\n        <li><span>Métrorragies post-menstruelles</span> par insuffisance œstrogénique en début de cycle.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 24 — Complications de la grossesse · 300 — Tumeur col-corps utérin · 41 — Endométrisose · 36 — Contraception · 37 — IVG</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de ménorragies","contenu":"<div class=\"notion-course\"><p>Les <span>ménorragies</span> = règles <strong>anormalement abondantes</strong> (&gt; <span>80 mL</span>) et/ou <strong>prolongées</strong> (&gt; <span>7 jours</span>). Quand elles s'associent à des saignements inter-menstruels, on parle de <span>méno-métrorragies</span>. La quantification objective repose sur le <span>score de Higham</span> : on parle de ménorragies pour un <span>score</span> <span>&gt; 100</span>. La démarche distingue <span <span=\"\">&gt;3</span> grands cadres :</p>\n\n      <table>\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Organiques utérines</strong></td>\n            <td>\n              <span>Fibromes utérins</span> +++ (surtout <strong>sous-muqueux</strong> et <strong>interstitiels</strong>) ;<br>\n              <span>Adénomyose</span> ;<br>\n              <span>Polypes endométriaux</span> ;<br>\n              <span>Hyperplasie endométriale</span> ± atypique ;<br>\n              <span>Cancer de l'endomètre</span> ;<br>\n              <span>Malformations utérines</span> ; <span>cicatrice de césarienne</span> (isthmocèle).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnelles</strong></td>\n            <td>\n              <span>Dysovulation / anovulation</span> chronique → endomètre proliféré non opposé par la progestérone ;<br>\n              Particulièrement fréquent en <strong>péri-ménarche</strong> et en <strong>périménopause</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Trouble de l'hémostase</strong></td>\n            <td>\n              <span>Maladie de Willebrand</span> +++ (à évoquer chez l'<strong>adolescente</strong> avec ménorragies dès la ménarche) ;<br>\n              <span>Thrombopénies</span> (PTI, hémopathies) ;<br>\n              <span>Traitements anticoagulants</span> / <span>antiagrégants</span> ;<br>\n              <span>Insuffisance hépatique</span> sévère, coagulopathies de consommation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes contraception</strong></td>\n            <td>\n              <span>DIU au cuivre</span> : majore l'abondance et la durée des règles ;<br>\n              <span>Microprogestatifs</span> à l'inverse : peuvent provoquer spottings/aménorrhée plutôt que ménorragies.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes</strong></td>\n            <td>\n              <span>Hypothyroïdie</span> (peut majorer les ménorragies) ;<br>\n              <span>SOPK</span> (rare ménorragie pure — plus souvent spaniomé/aménorrhée puis hémorragies de privation abondantes).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — réflexe.</strong> Une adolescente avec ménorragies sévères dès la ménarche → <span>évoquer un trouble de l'hémostase</span> (maladie de Willebrand surtout) en plus du bilan habituel (β-hCG, <span>NFS</span>, <span>échographie</span>).\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitements généraux (quelle que soit l'étiologie).</strong> Selon le Collège CNGOF :\n        <ul>\n          <li><span>Antifibrinolytique</span> : acide tranexamique (Exacyl®) ;</li>\n          <li><span>Traitement martial</span> per os ou IV ;</li>\n          <li><strong>Transfusion</strong> si besoin.</li>\n        </ul>\n        Puis traitement <strong>étiologique</strong> : polype (résection hystéroscopique), adénomyose et myome (DIU au lévonorgestrel en 1ʳᵉ intention, <span>chirurgie</span> sinon), hyperplasie sans atypie (progestatifs PO ou DIU LNG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin · 41 — Endométrisose · 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-8","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’aménorrhée primaire","contenu":"<div class=\"notion-course\"><p><span>Aménorrhée primaire</span> = absence de ménarche après <span>15 ans</span> en présence d'un développement pubertaire normal, ou à <span>13 ans</span> en l'absence de tout signe de puberté. La démarche s'organise <strong>selon la présence ou non d'un développement pubertaire</strong> et selon les anomalies utéro-vaginales associées.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe Collège — 2 diagnostics en cas d'absence d'utérus à l'<span>échographie</span>.</strong> Bien différencier :\n        <ul>\n          <li><span>Agénésie müllérienne (MRKH)</span> : aplasie <span>congénitale</span> de l'utérus et des 2/3 supérieurs du vagin, caryotype <strong>46,XX</strong>, caractères sexuels secondaires normaux ;</li>\n          <li><span>Insensibilité complète aux androgènes (Morris)</span> : caryotype <strong>46,XY</strong>, phénotype féminin, testicules intra-abdominaux/inguinaux — <em>cause exceptionnelle</em>.</li>\n        </ul>\n      </div>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies anatomiques</strong> (filière génitale)</td>\n            <td>\n              <span>Imperforation hyménale</span> (hématocolpos, douleurs cycliques) ;<br>\n              <span>Malformations müllériennes</span> : agénésie / hypoplasie utérine, cloisons vaginales transverses ;<br>\n              <span>Syndrome de Mayer-Rokitansky-Küster-Hauser (MRKH)</span> : agénésie utéro-vaginale, ovaires fonctionnels, caryotype 46,XX ;<br>\n              <span>Syndrome d'insensibilité aux androgènes (Morris)</span> : phénotype féminin, caryotype 46,XY, testicules ectopiques.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anomalies chromosomiques / dysgénésies gonadiques</strong></td>\n            <td>\n              <span>Syndrome de Turner</span> (45,X et mosaïques) +++ : petite taille, dysgénésie gonadique, impubérisme, FSH élevée ;<br>\n              Dysgénésies gonadiques pures 46,XX ou 46,XY (<span>syndrome de Swyer</span>) ;<br>\n              Trisomies, anomalies du chromosome X.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypogonadisme hypogonadotrope</strong> (cause centrale)</td>\n            <td>\n              <span>Retard pubertaire constitutionnel</span> (diagnostic d'élimination) ;<br>\n              <span>Syndrome de Kallmann</span> (déficit GnRH + anosmie) ;<br>\n              <span>Hyperprolactinémie</span> (adénome hypophysaire, médicamenteuse) ;<br>\n              Pathologies hypothalamo-hypophysaires (craniopharyngiome, tumeurs sellaires, <span>irradiation</span>) ;<br>\n              <span>Anorexie mentale</span>, dénutrition sévère, activité physique intense.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies endocriniennes / chroniques</strong></td>\n            <td>\n              <span>Hypothyroïdie</span> sévère ;<br>\n              <span>Hyperplasie congénitale des surrénales</span> (bloc en 21-hydroxylase) ;<br>\n              Maladies chroniques sévères (<span>MICI</span>, <span>insuffisance rénale</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’aménorrhée secondaire","contenu":"<div class=\"notion-course\"><p><span>Aménorrhée secondaire</span> = arrêt des règles <span>≥ 3 mois consécutifs</span> chez une femme antérieurement réglée. La démarche étiologique s'appuie sur l'<strong>algorithme du <span class=\"nc-blue_bg\">bilan hormonal</span></strong> (cf obj-10) qui classe les causes en <strong>3 cadres</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Réflexe 1ᵉʳ.</strong> Avant tout bilan, <span>éliminer une <span class=\"nc-brown_bg\">grossesse</span></span> — la 1ʳᵉ cause d'aménorrhée secondaire chez une femme en âge de procréer reste la <span><span class=\"nc-brown_bg\">grossesse</span></span>. <span>β-hCG plasmatique</span> systématique.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 1 — FSH/LH/œstradiol bas → cause centrale (hypothalamo-hypophysaire)</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hyperprolactinémie</strong> (prolactine ↑)</td>\n            <td>\n              <span>Adénome hypophysaire à prolactine (prolactinome)</span> +++ ;<br>\n              <strong>Hyperprolactinémie médicamenteuse</strong> (<span>neuroleptiques</span>, antiémétiques, antidépresseurs, <span>opiacés</span>) ;<br>\n              <span>Hypothyroïdie</span> périphérique (TRH ↑ → PRL ↑) ; <span>insuffisance rénale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres causes centrales</strong> (prolactine normale)</td>\n            <td>\n              <span>Aménorrhée hypothalamique fonctionnelle</span> : <span>anorexie mentale</span>, dénutrition, sport intensif, stress chronique ;<br>\n              <span>Syndrome de Sheehan</span> (<span>nécrose</span> hypophysaire du post-partum <span>hémorragique</span>) ;<br>\n              <span>Craniopharyngiome</span>, tumeurs sellaires, hypophysite, séquelles d'<span>irradiation</span>/<span>chirurgie</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 2 — FSH/(LH)/œstradiol normaux → cause utéro-vaginale ou SOPK</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>SOPK</strong> (syndrome des ovaires polykystiques) +++</td>\n            <td><span>5 à 10 %</span> des femmes en âge de procréer. <em>Cause la plus fréquente d'anovulation et d'aménorrhée secondaire normo-œstrogénique</em> ; test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> positif. <strong><span>Critères de</span> Rotterdam</strong> (2/3 suffisent, après exclusion des autres causes) : oligo/anovulation ; hyperandrogénie clinique/bio ; aspect échographique d'<span>ovaires polymicrokystiques</span> (<span>≥ 12 follicules de 2-9 mm</span> par ovaire et/ou volume ovarien <span>&gt; 10 mL</span>). Doser la <span>17-OH-progestérone</span> pour éliminer un bloc en 21-hydroxylase ; <span>AMH</span> élevée.</td>\n          </tr>\n          <tr>\n            <td><strong>Causes utéro-vaginales acquises</strong></td>\n            <td>\n              <span>Synéchies utérines</span> (syndrome d'Asherman) — post-<span>curetage</span>, post-endométrite ;<br>\n              Sténoses cervicales post-conisation, post-chirurgicales.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 3 — FSH/(LH) élevées + œstradiol bas → insuffisance ovarienne</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Insuffisance ovarienne prématurée (IOP)</strong></td>\n            <td>\n              <span>Aménorrhée &gt; 4 mois avant 40 ans + FSH &gt; 25 UI/l</span> (sur 2 dosages) + signes d'hypo-œstrogénie. Hypogonadisme <strong>hypergonadotrope</strong> ; ne répond pas au <span class=\"nc-yellow_bg\">test aux progestatifs</span>. Concerne <span>1 % des femmes &lt; 40 ans</span> (<span>0,1 %</span> avant <span>30 ans</span>). Étiologies : <em>idiopathique dans <span>80 %</span> des cas</em>, génétiques (Turner, prémutation X fragile FMR1, polyendocrinopathies), <span>iatrogène</span> (chimio, <span>radiothérapie</span>, <span>chirurgie</span> ovarienne), <span>auto-immune</span> (Addison). Faire caryotype + recherche prémutation FMR1 + bilan auto-immun.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ménopause</strong></td>\n            <td>Aménorrhée &gt;<span> 12 mois</span> chez une femme &gt;<span> 45-50 ans</span> en moyenne, avec FSH élevée et symptômes climatériques.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 253 — <span>Obésité</span> · 38 — Infertilité du couple</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies de spanioménorrhée","contenu":"<div class=\"notion-course\"><p>La <span>spanioménorrhée</span> = cycles <span>&gt; 35 jours</span> (souvent &gt; 45 j = oligospanioménorrhée), c'est-à-dire des règles <strong>espacées et peu fréquentes</strong>. Elle correspond souvent à une <strong>forme fruste</strong> des étiologies d'aménorrhée secondaire — l'ovulation est irrégulière mais non totalement absente.</p>\n\n      <table>\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Endocrino-ovariennes</strong></td>\n            <td>\n              <span>SOPK</span> +++ — <em>cause de loin la plus fréquente</em>, sur <span>terrain</span> d'hyperandrogénie ± insulinorésistance ;<br>\n              <span>Insuffisance ovarienne débutante</span> (forme infraclinique précoce de l'IOP) ;<br>\n              <span>Périménopause</span> : raccourcissement puis allongement progressif des cycles avant aménorrhée définitive.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypothalamo-hypophysaires</strong></td>\n            <td>\n              <span>Hyperprolactinémie modérée</span> (médicamenteuse, microadénome) ;<br>\n              <span>Aménorrhée hypothalamique fonctionnelle</span> dans ses formes débutantes : <span>anorexie</span> / dénutrition modérée, sport intensif, stress chronique.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes générales</strong></td>\n            <td>\n              <span>Dysthyroïdies</span> (hypo- comme <span>hyperthyroïdie</span>) ;<br>\n              <span>Hyperplasie congénitale des surrénales</span> à révélation tardive ;<br>\n              <span>Hypercorticisme</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métaboliques</strong></td>\n            <td><span>Obésité</span> sévère (lien avec SOPK), <em>très bas poids</em> / dénutrition.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant une spanioménorrhée chez une femme jeune, le <span>SOPK</span> est l'hypothèse à éliminer en 1ʳᵉ intention (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> + <span class=\"nc-blue_bg\">bilan hormonal</span> + testostérone totale + SHBG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 253 — <span>Obésité</span> · 38 — Infertilité du couple</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan à réaliser pour le diagnostic des aménorrhées et des troubles du cycle","contenu":"<div class=\"notion-course\"><p>Le bilan d'une aménorrhée ou d'un trouble du cycle s'articule en 3 temps : <strong>1ʳᵉ intention</strong> (test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span>), <strong><span class=\"nc-blue_bg\">bilan hormonal</span></strong> et <strong>imagerie</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Préalable systématique.</strong> <span>β-hCG plasmatique</span> avant toute exploration — <span>éliminer une <span class=\"nc-brown_bg\">grossesse</span></span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Orientation à l'examen clinique (CAT Collège).</strong> Avant les dosages, rechercher :\n        <ul>\n          <li><span>Signes d'hyperandrogénie</span> : hirsutisme (<span>score de Ferriman-Galwey &gt; 6</span>), acné sévère, alopécie androgénique du vertex → oriente vers un <span>SOPK</span> ;</li>\n          <li><span>Galactorrhée</span> : association aménorrhée-galactorrhée très évocatrice d'<span>hyperprolactinémie</span> ;</li>\n          <li><span>Signes de carence œstrogénique</span> : bouffées vasomotrices, sécheresse vaginale, dyspareunie, troubles du sommeil/psychiques, perte de libido ;</li>\n          <li><strong>Poids / IMC / fluctuations pondérales</strong>, <span>TCA</span>, érythrocyanose des extrémités + lanugo (signes d'hypométabolisme) → <span>aménorrhée hypothalamique fonctionnelle</span>.</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1ʳᵉ intention — <span class=\"nc-yellow_bg\">test aux progestatifs</span> (<span class=\"nc-pink nc-bold\">dydrogestérone</span>)</h4>\n      <p>1ᵉʳ test à réaliser devant toute aménorrhée <strong>secondaire</strong>, dans le but de déclencher une <em>hémorragie de privation</em>. Apport diagnostique limité (FP/FN importants), mais il oriente la suite du bilan.</p>\n\n      <table>\n        <thead><tr><th>Paramètre</th><th>Résultat / interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>Administration d'un <span><span class=\"nc-pink_bg\">progestatif</span></span> (généralement <span><span class=\"nc-pink nc-bold\">dydrogestérone</span></span>) <em>per os</em>, <span>10 à 20 mg/j pendant <span class=\"nc-pink nc-bold\">7-10 jours</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Test positif</strong></td>\n            <td>\n              <strong>Définition</strong> : survenue des <span class=\"nc-green_bg\">menstruations dans les </span><span><span class=\"nc-green_bg\">5 jours</span></span><span class=\"nc-green_bg\"> suivant l'arrêt</span> du <span class=\"nc-pink_bg\">progestatif</span> ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>imprégnation œstrogénique de l'endomètre suffisante</strong> ;<br>\n              Si aménorrhée + test positif = <span>aménorrhée par anovulation normo-œstrogénique</span> (ex. <span>SOPK</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Test négatif</strong></td>\n            <td>\n              <strong>Définition</strong> : <span class=\"nc-red_bg\">absence d'hémorragie</span> de privation ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>carence œstrogénique</strong> (pas de croissance endométriale). Causes :<br>\n              <span><span class=\"nc-orange_bg\">Hypofonctionnement ovarien sévère</span></span> (atrophie endométriale par hypo-œstrogénie, indépendamment de sa cause) ;<br>\n              <span><span class=\"nc-orange_bg\">Anomalie anatomique de la filière génitale</span></span> ;<br>\n              <strong><span><span class=\"nc-brown_bg\">Grossesse</span></span></strong> (malgré l'imprégnation œstrogénique, la progestérone endogène est maintenue → pas d'hémorragie de privation).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Suites diagnostiques</strong></td>\n            <td>\n              <span class=\"nc-blue_bg\">Bilan hormonal</span> + <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> :<br>\n              Si test <strong>positif</strong> : examens complémentaires <span><span class=\"nc-pink nc-bold\">3 jours</span></span><span class=\"nc-pink nc-bold\"> après</span> le cycle déclenché ;<br>\n              Si test <strong>négatif</strong> (ou absence de test) : examens complémentaires peuvent être réalisés en aménorrhée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Limite du test.</strong> Il n'est qu'une <em>indication diagnostique</em> — taux de <span>faux positifs et faux négatifs important</span>. Ne dispense jamais d'un <span class=\"nc-blue_bg\">bilan hormonal</span> complet.\n      </div>\n\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"nc-blue_bg\">Bilan hormonal</span> — au moment des règles (<span>J2</span>-J5)</h4>\n      <p>Dosages : <span>β-hCG</span>, <span>FSH</span>, <span>œstradiol</span>, <span>prolactine</span> ± <span>LH</span>. Bilan à réaliser au moment des règles (<span>J2-J5 du cycle</span>) pour être interprété correctement, donc :</p>\n      <ul>\n        <li>Soit <strong>directement</strong> si le test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> est négatif ;</li>\n        <li>Soit <span><span class=\"nc-pink nc-bold\">3 jours après</span></span> un test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> positif.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique du <span class=\"nc-blue_bg\">bilan hormonal</span> (algorithme Collège)</h4>\n      <table>\n        <thead><tr><th>Profil hormonal</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FSH, LH, œstradiol bas</strong></td>\n            <td>\n              <span>Cause centrale</span> :<br>\n              <strong>Prolactine élevée</strong> → <span>hyperprolactinémie</span> (prolactinome, médicamenteuse) ;<br>\n              <strong>Prolactine normale</strong> → <span>autres causes centrales</span> (aménorrhée hypothalamique fonctionnelle, Sheehan, craniopharyngiome).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH), œstradiol normaux</strong></td>\n            <td>\n              <span>Cause utéro-vaginale</span> ou <span>SOPK</span> ;<br>\n              <strong>Apport de l'<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> +++</strong> (ovaires polykystiques, synéchies, anomalie filière).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH) élevées + œstradiol bas</strong></td>\n            <td><span>Insuffisance ovarienne prématurée</span> (avant <span>40 ans</span>) ou ménopause physiologique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie</h4>\n      <p><span><span class=\"nc-blue_bg\">Échographie pelvienne</span></span> (sus-pubienne ± endovaginale) — recherche :</p>\n      <ul>\n        <li><strong>Anomalie de la filière génitale</strong> : agénésie utérine, synéchies, malformations müllériennes ;</li>\n        <li><strong>Pathologie ovarienne</strong> : aspect d'<span>ovaires polykystiques</span>, kystes, atrophie ovarienne (IOP).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>En 2ᵈ intention</strong> selon l'orientation : <span>IRM hypophysaire</span> (si hyperprolactinémie ou suspicion centrale), <span>caryotype</span> (Turner, dysgénésies), bilan <span>auto-immun</span> (IOP), <span>testostérone totale + SHBG</span> (SOPK, hyperandrogénie), <span>TSH</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 38 — Infertilité du couple</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","contenu":"<div class=\"notion-course\"><p>Bilan structuré devant des saignements utérins : <strong>clinique</strong> → <strong>biologie</strong> → <strong>imagerie</strong> ± <strong><span>endoscopie</span></strong>. La <span>β-hCG est systématique</span> chez toute femme en âge de procréer.</p>\n\n      <h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Examen clinique</h4>\n      <table>\n        <thead><tr><th>Temps</th><th>Éléments à recueillir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              Caractéristiques du saignement (date début, abondance, durée, déclenchement, saignements intermenstruels <span>vs</span> règles abondantes) ;<br>\n              <strong>ATCD</strong> : gynécologiques, obstétricaux, FCV à jour, contraception, ATCD personnel/familial de cancer gynéco ;<br>\n              Signes associés : douleurs pelviennes, dyspareunie, leucorrhées, signes endocriniens.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen physique</strong></td>\n            <td>\n              <span>Examen au spéculum</span> +++ (origine du saignement : col, vagin, endo-utérin ? <span>lésion</span> visible ?) ;<br>\n              <span>Toucher vaginal</span> (taille/forme/mobilité utérus, masses annexielles) ;<br>\n              Examen général : <span>pâleur</span>, <span>tachycardie</span>, signes de retentissement hémodynamique.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Biologie</h4>\n      <ul>\n        <li><span>β-hCG plasmatique</span> +++ chez toute femme en âge de procréer ;</li>\n        <li><span>NFS-plaquettes</span> et <span>bilan martial</span> : <span>ferritinémie + CRP</span> (un <span>syndrome <span>inflammatoire</span></span> peut masquer une hypoferritinémie) ;</li>\n        <li><span>TP/TCA</span> et <span>dosage du facteur Willebrand</span> (<em>indication large chez l'adolescente</em>), voire bilan d'hémostase complet si suspicion (contexte familial, <span>anticoagulant</span>) ;</li>\n        <li><span>Groupe-Rh-RAI</span> si saignement abondant ;</li>\n        <li><span>FCV / test HPV</span> selon âge et <span>dépistage</span> à jour.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie de 1ʳᵉ intention</h4>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Échographie pelvienne</span> sus-pubienne + endovaginale</span> +++ : <strong>épaisseur de l'endomètre</strong>, fibromes (nombre/localisation/taille), polypes, ovaires, masses annexielles, signes de GEU/<span><span class=\"nc-brown_bg\">grossesse</span></span> intra-utérine.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2ᵈ intention</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hystéroscopie diagnostique</strong></td>\n            <td>\n              Suspicion de <span>pathologie endo-utérine</span> (polype, fibrome sous-muqueux, hyperplasie, cancer) ;<br>\n              Bilan systématique en cas de <span>métrorragies post-ménopausiques</span> avec <span>endomètre</span> &gt; <span>4-5 mm</span> à l'écho.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Biopsie</span> endométriale</strong></td>\n            <td>Indiquée chez <span>toute patiente &gt; 45 ans</span> ou en cas de <span>facteur de risque</span> de cancer de l'endomètre. Par pipelle de Cornier ou biopsies dirigées sous hystéroscopie — analyse histologique (hyperplasie, atypies, <span>cancer de l'endomètre</span>). <em>⚠️ Faite à l'aveugle, ne peut éliminer avec certitude un cancer même si normale.</em></td>\n          </tr>\n          <tr>\n            <td><strong><span>IRM</span> pelvienne</strong></td>\n            <td>Caractérisation de lésions complexes (fibromes nombreux, adénomyose, <span>bilan préopératoire</span>, suspicion de cancer du corps utérin).</td>\n          </tr>\n          <tr>\n            <td><strong>Hystérosalpingographie</strong></td>\n            <td>Plus rare dans ce contexte — utile si suspicion de synéchies utérines.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Toute métrorragie post-ménopausique impose l'hystéroscopie + <span>biopsie</span> endométriale</strong> — c'est un <span>cancer de l'endomètre jusqu'à preuve du contraire</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 300 — Tumeur col-corps utérin · 24 — Complications de la grossesse · 312 — Tumeur sein</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0},{"id":"35-13","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître les situations d’urgence en cas de saignements utérins","contenu":"<div class=\"notion-course\"><p>Plusieurs scénarios imposent une <strong>prise en charge urgente</strong> devant des saignements utérins. À reconnaître au moindre signe d'appel.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Savoir évaluer les pertes sanguines &amp; la gravité</h4>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Quantification</strong></td>\n            <td>Interrogatoire (garnitures, caillots, vêtements tachés), <span>score de Higham</span> (&gt; 100 = ménorragies), spéculum (saignement actif ?), <span>HemoCue® / NFS</span> (taux d'<span>hémoglobine</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Anémie mal tolérée</strong></td>\n            <td><span>Tachycardie</span>, <span>pâleur</span> cutanéo-muqueuse et conjonctivale, <span>dyspnée</span>, <span>asthénie</span>, <span>vertiges</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes de <span>choc</span></strong></td>\n            <td><span>Hypotension</span>, <span>malaise</span>, <span>sueurs</span>, extrémités froides, marbrures.</td>\n          </tr>\n          <tr>\n            <td><strong>Mise en condition</strong> (si <span>choc</span> / anémie mal tolérée)</td>\n            <td><span>Hospitalisation</span>, <span>2 VVP de bon calibre</span>, réchauffement, <span>oxygénothérapie</span>, bilan bio (<span>NFS</span>, hémostase, groupe + rhésus 2 déterminations, bilan prétransfusionnel, β-hCG sauf <span>grossesse</span> IU connue).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>1. <span>Grossesse</span> extra-utérine (GEU) rompue.</strong>\n        <ul>\n          <li><span>Femme en âge de procréer</span> + <span>métrorragies</span> ± <span>douleur pelvienne brutale</span> + <span>retard de règles</span> ;</li>\n          <li>Signes péritonéaux, hémopéritoine, scapulalgie (irritation phrénique) ;</li>\n          <li><span>Choc hémorragique</span> possible — collapsus, <span>tachycardie</span>, <span>pâleur</span> ;</li>\n          <li><strong>CAT</strong> : <span>β-hCG urgente</span> + <span><span class=\"nc-blue_bg\">échographie pelvienne</span> endovaginale</span> + <strong>bloc</strong> (cœlioscopie d'<span>urgence</span>).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>2. Hémorragie sévère / <span>choc</span> <span>hémorragique</span> (toutes causes).</strong>\n        <ul>\n          <li><span>Tachycardie</span>, <span>hypotension artérielle</span>, <span>pâleur</span>, marbrures, <span>sueurs</span>, troubles de la conscience ;</li>\n          <li>Saignement extériorisé abondant et persistant ;</li>\n          <li><strong>CAT</strong> : 2 VVP de gros calibre, <span>groupe-Rh-RAI + NFS + hémostase</span> en <span>urgence</span>, <strong>remplissage</strong> par cristalloïdes, <strong>transfusion</strong> de CGR ± PFC/<span>plaquettes</span> si critères, geste d'<strong>hémostase</strong> (utérotoniques, tamponnement, embolisation, <span>chirurgie</span> selon contexte).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>3. Contexte du post-partum — hémorragie de la délivrance / atonie utérine.</strong>\n        <ul>\n          <li>Saignement &gt; <span>500 mL</span> (voie basse) / <span>1000 mL</span> (césarienne) dans les <span>24h</span> ;</li>\n          <li><span>Globe utérin de sécurité absent</span>, utérus mou ;</li>\n          <li><strong>CAT</strong> : révision utérine, massage, <span>oxytocine</span> puis <span>sulprostone</span>, embolisation/<span>chirurgie</span> d'hémostase si échec.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>4. Drapeaux diagnostiques à ne pas manquer (semi-urgents).</strong>\n        <ul>\n          <li><span>Toute métrorragie post-ménopausique</span> = cancer de l'endomètre jusqu'à preuve du contraire — exploration en consultation rapide (<span>échographie</span> + hystéroscopie/<span>biopsie</span>) ;</li>\n          <li><span>Métrorragies provoquées post-coïtales chez la femme jeune</span> → cancer du col utérin à éliminer (examen au spéculum, FCV, <span>biopsie</span> cervicale dirigée si <span>lésion</span>) ;</li>\n          <li><span>Anémie chronique mal tolérée</span> (<span>asthénie</span> majeure, <span>dyspnée</span>, <span>angor</span>) sur ménorragies prolongées.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 24 — Complications de la grossesse</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Ménorragies, 2022</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>GEU rompue <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale absolue</span></strong></p><p><span class=\"kw-bio\">β-hCG urgente</span> + <span class=\"kw-imagerie\">échographie endovaginale</span> → <span class=\"kw-ttt\">cœlioscopie d'hémostase</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-clinique\">Métrorragies</span> + <span class=\"kw-clinique\">douleur pelvienne brutale</span> + <span class=\"kw-clinique\">retard de règles</span> chez une femme en âge de procréer</li><li>Signes péritonéaux, <span class=\"kw-clinique\">scapulalgie</span> (irritation phrénique), <span class=\"kw-alerte\">hémopéritoine</span></li><li><span class=\"kw-alerte\">Choc hémorragique</span> possible : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pâleur</span></li></ul><p><strong>Hémorragie sévère / <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— toutes causes</span></strong></p><p><span class=\"kw-ttt\">2 VVP de gros calibre</span> · remplissage cristalloïdes · <span class=\"kw-bio\">groupe-Rh-RAI + NFS + hémostase</span> · <span class=\"kw-ttt\">transfusion de CGR</span> ± PFC/<span class=\"kw-bio\">plaquettes</span> si critères · geste d'hémostase</p><ul><li><span class=\"kw-alerte\">Hypotension</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">pâleur</span>, marbrures, <span class=\"kw-clinique\">sueurs</span>, troubles de la conscience</li><li>Saignement extériorisé <strong>abondant et persistant</strong></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Urgence</span> immédiate (<span class=\"kw-alerte\">hospitalisation</span>) :</strong> <span class=\"kw-alerte\">GEU rompue</span>, <span class=\"kw-alerte\">choc hémorragique</span>, <span class=\"kw-clinique\">anémie mal tolérée</span> (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">malaise</span>).<br><strong>Consultation rapide (&lt;<span class=\"kw-chiffre\"> 72 h</span>) :</strong> <span class=\"kw-alerte\">métrorragie post-ménopausique</span> (cancer de l'endomètre jusqu'à preuve du contraire) · <span class=\"kw-alerte\">métrorragie post-coïtale</span> répétée (cancer du col).<br><strong>Ambulatoire :</strong> métrorragies isolées sans <span class=\"kw-alerte\">signe de gravité</span> ni contexte à risque — bilan en consultation programmée.</p>","redflags":"<ul><li><span class=\"kw-alerte\">GEU</span> — toute métrorragie + <span class=\"kw-clinique\">retard de règles</span> chez une femme en âge de procréer : <span class=\"kw-bio\">β-hCG</span> systématique, GEU à éliminer en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">Métrorragie post-ménopausique</span> = <span class=\"kw-etio\">cancer de l'endomètre</span> jusqu'à preuve du contraire (<span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-imagerie\">hystéroscopie</span> + <span class=\"kw-bio\">biopsie</span> endométriale)</li><li><span class=\"kw-alerte\">Métrorragies provoquées post-coïtales</span> chez la femme jeune → <span class=\"kw-etio\">cancer du col utérin</span> à éliminer (examen au spéculum + <span class=\"kw-bio\">FCV</span> + <span class=\"kw-bio\">biopsie cervicale</span> dirigée si <span class=\"kw-clinique\">lésion</span> visible)</li><li><span class=\"kw-alerte\">Choc hémorragique</span> : <span class=\"kw-clinique\">hypotension</span> · <span class=\"kw-clinique\">tachycardie</span> · marbrures · troubles de la conscience</li><li><span class=\"kw-alerte\">Anémie chronique mal tolérée</span> (<span class=\"kw-clinique\">asthénie</span> majeure, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">angor</span>) sur ménorragies prolongées</li></ul>","principes":"<p>Démarche en <strong>2 temps</strong> : éliminer d'abord une <span class=\"kw-alerte\">urgence vitale</span> (<span class=\"kw-alerte\">GEU</span>, <span class=\"kw-alerte\">choc</span>), puis enquête étiologique (<span class=\"kw-bio\">β-hCG</span> · <span class=\"kw-imagerie\">échographie</span> · <span class=\"kw-imagerie\">hystéroscopie</span> selon contexte).</p><p><strong>Traitements généraux des saignements utérins</strong></p><p>puis traitement <strong>étiologique</strong> selon la cause identifiée</p><ul><li><span class=\"kw-ttt\">Acide tranexamique</span> (Exacyl®) — antifibrinolytique, quel que soit le mécanisme</li><li><span class=\"kw-ttt\">Traitement martial</span> per os ou IV — corriger l'<span class=\"kw-bio\">anémie ferriprive</span></li><li><span class=\"kw-ttt\">Transfusion de CGR</span> si critères hémodynamiques ou <span class=\"kw-bio\">Hb</span> basse mal tolérée</li></ul><p><strong>Traitement étiologique — grandes lignes</strong></p><ul><li><span class=\"kw-etio\">Polype</span> → résection hystéroscopique</li><li><span class=\"kw-etio\">Fibrome sous-muqueux / adénomyose</span> → <span class=\"kw-ttt\">DIU au lévonorgestrel</span> en 1ʳᵉ intention, <span class=\"kw-ttt\">chirurgie</span> sinon</li><li><span class=\"kw-etio\">Hyperplasie endométriale sans atypie</span> → <span class=\"kw-ttt\">progestatifs PO</span> ou <span class=\"kw-ttt\">DIU LNG</span></li><li><span class=\"kw-etio\">Cause iatrogène (DIU cuivre, microprogestatif)</span> → <span class=\"kw-def\">réévaluation</span> contraception</li><li><span class=\"kw-ci\">Cancer de l'endomètre / du col</span> → orientation oncologique urgente</li></ul><p><strong>Cas particulier — adolescente avec ménorragies sévères</strong></p><ul><li>Évoquer un <span class=\"kw-etio\">trouble de l'hémostase</span> en plus du bilan habituel</li><li><span class=\"kw-etio\">Maladie de Willebrand</span> +++ : <span class=\"kw-bio\">facteur Willebrand</span> + <span class=\"kw-bio\">TP/TCA</span> systématiques si ménorragies dès la ménarche</li></ul>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Quel trouble prédomine ?","detail":"<ul><li>Calendrier, retentissement, contraception et grossesse possible.</li></ul>","branches":[{"label":"Saignement","to":"saignement"},{"label":"Aménorrhée / cycles espacés","to":"ameno"},{"label":"Symptômes prémenstruels","to":"spm"}]},{"id":"saignement","kind":"decision","label":"Gravité ou anémie importante ?","detail":"<ul><li>Tolérance, grossesse et causes organiques/fonctionnelles.</li></ul>","branches":[{"label":"Oui","to":"urgent"},{"label":"Non","to":"bilan"}]},{"id":"urgent","kind":"urgent","label":"Stabiliser et contrôler le saignement","detail":"<ul><li>Prise en charge gynécologique urgente selon contexte.</li></ul>","branches":[]},{"id":"bilan","kind":"finish","label":"Bilan orienté et imagerie si indiquée","detail":"<ul><li>NFS/ferritine, hémostase si contexte ; exploration endométriale selon âge/risque.</li></ul>","branches":[]},{"id":"ameno","kind":"finish","label":"Exclure grossesse puis bilan hormonal/anatomique","detail":"<ul><li>Utiliser les arbres d’aménorrhée ; primaire/secondaire et hyperandrogénie.</li></ul>","branches":[]},{"id":"spm","kind":"finish","label":"Vérifier la cyclicité et le retentissement","detail":"<ul><li>Journal prospectif, diagnostics différentiels et prise en charge partagée.</li></ul>","branches":[]}]},"cards":[{"i":"01c9742cd318","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Qu'est-ce que le trouble dysphorique prémenstruel ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red nc-bold\">trouble dysphorique prémenstruel</span> est une <strong>forme psychiatrique invalidante</strong> du syndrome prémenstruel (SPM), caractérisée par des syndromes psychiatriques cycliques et un retentissement sur la qualité de vie.</p></div>"},{"i":"04e27c5eee7e","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quels sont les trois grandes catégories de signes cliniques classiquement associés au syndrome prémenstruel (SPM) ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>mastodynies</strong> (douleurs ou tension mammaire).</li><li>Les <strong><span class=\"nc-yellow_bg\">signes abdomino-pelviens</span></strong> (<span class=\"nc-blue_bg\">ballonnement abdominal</span>, troubles du transit, prise de poids transitoire).</li><li>Les <strong><span class=\"nc-yellow_bg\">signes neuropsychologiques</span></strong> (<span class=\"nc-blue_bg\">céphalées</span>, <span class=\"nc-blue_bg\">irritabilité</span>, <span class=\"nc-blue_bg\">anxiété</span>, <span class=\"nc-blue_bg\">syndrome dépressif</span>).</li></ul></div>"},{"i":"a39323b21ddc","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quelle est la définition du syndrome prémenstruel (SPM) ?","a":"<div class=\"notion-course\"><p>Le syndrome prémenstruel (SPM) est un ensemble de <strong>manifestations bénignes</strong>, physiques et psychologiques, qui apparaissent de façon <strong>cyclique</strong> dans les jours précédant les règles et disparaissent <span class=\"nc-green_bg\">au début ou au cours des menstruations</span>.</p></div>"},{"i":"c102d61cca86","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quelle est la fréquence du syndrome prémenstruel (SPM) chez les femmes en âge de procréer ?","a":"<div class=\"notion-course\"><p>Le syndrome prémenstruel (SPM) est la gêne fonctionnelle la plus fréquemment signalée, touchant <strong><span class=\"nc-pink nc-bold\">30 à 40 %</span> des femmes</strong> en âge de procréer.</p></div>"},{"i":"0190190879f4","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quels sont les examens biologiques supplémentaires à envisager face à des méno-métrorragies ?","a":"<div class=\"notion-course\"><ul><li><strong>NFS-plaquettes et bilan martial</strong> (ferritinémie + CRP) pour évaluer un retentissement et dépister une carence martiale.</li><li><strong>TP/TCA et dosage du facteur Willebrand</strong>, particulièrement chez l'adolescente, ou un bilan d'hémostase complet en cas de suspicion de trouble de l'hémostase (antécédents familiaux, prise d'anticoagulants).</li><li><strong>Groupe-Rh-RAI</strong> en cas de saignement abondant.</li><li>Réalisation/vérification du <strong>FCV ou test HPV</strong> selon l'âge et le dépistage en cours.</li></ul></div>"},{"i":"1e8d777de47c","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quel est le premier examen biologique à réaliser systématiquement devant des méno-métrorragies chez toute femme en âge de procréer ?","a":"<div class=\"notion-course\"><p>Devant des méno-métrorragies chez toute femme en âge de procréer, il faut systématiquement réaliser un dosage de la <strong>β-hCG plasmatique</strong> afin d'éliminer ou confirmer une grossesse (notamment une grossesse extra-utérine).</p></div>"},{"i":"6ad3835dde96","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quelle est la particularité de la prise en charge d'une métrorragie survenant après la ménopause ?","a":"<div class=\"notion-course\"><p>Toute métrorragie survenant <strong>après la ménopause</strong> est considérée comme suspecte et impose systématiquement la réalisation d'une <strong>hystéroscopie avec biopsie endométriale</strong>. En effet, toute métrorragie post-ménopausique doit être considérée comme un <strong>cancer de l'endomètre jusqu'à preuve du contraire</strong>.</p></div>"},{"i":"cc9d66e30f28","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quel est l'examen d'imagerie de première intention à réaliser devant des méno-métrorragies et quels éléments permet-il d'évaluer ?","a":"<div class=\"notion-course\"><p>L'examen d'imagerie de première intention est l'<strong><span class=\"nc-blue_bg\">échographie pelvienne</span> sus-pubienne et endovaginale</strong>. Elle permet d'évaluer :</p><ul><li>L'épaisseur de l'endomètre.</li><li>La présence de fibromes (nombre, localisation, taille).</li><li>La présence de polypes.</li><li>L'aspect des ovaires et d'éventuelles masses annexielles.</li><li>Des signes de grossesse intra-utérine ou extra-utérine.</li></ul></div>"},{"i":"f893eb9bd2fd","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Dans quelles situations doit-on envisager une hystéroscopie diagnostique et une biopsie endométriale comme examen de deuxième intention face à des méno-métrorragies ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>hystéroscopie diagnostique</strong> est indiquée en cas de suspicion de pathologie endo-utérine (polype, fibrome sous-muqueux, hyperplasie, cancer) ou systématiquement en cas de <strong>métrorragies post-ménopausiques</strong> avec un endomètre &gt; 4-5 mm à l'échographie.</li><li>Une <strong>biopsie endométriale</strong> est indiquée chez toute patiente de <strong>plus de 45 ans</strong> ou en cas de <strong>facteur de risque de cancer</strong> de l'endomètre. Toute métrorragie post-ménopausique impose l'hystéroscopie avec biopsie endométriale, car c'est un cancer de l'endomètre jusqu'à preuve du contraire.</li></ul></div>"},{"i":"36f8ef32570b","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Quelle est la méthode de comptage de la durée d'un cycle menstruel normal ?","a":"<div class=\"notion-course\"><p>La durée d'un cycle menstruel normal se compte du <strong>1<sup>er</sup> jour des règles</strong> jusqu'au <strong>1<sup>er</sup> jour des règles suivantes</strong>.</p></div>"},{"i":"3ad71ff15d09","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Quelles sont les caractéristiques des menstruations considérées comme normales ?","a":"<div class=\"notion-course\"><p>Les menstruations normales durent <strong>3 à 6 jours</strong> et correspondent à des pertes sanguines <strong>inférieures à 80 mL</strong>.</p></div>"},{"i":"413019f0ec39","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Comment définit-on un cycle menstruel normal ?","a":"<div class=\"notion-course\"><p>Un cycle menstruel normal est un <strong>cycle ovulatoire</strong> dont la durée varie typiquement entre <strong>25 et 35 jours</strong>.</p></div>"},{"i":"9c541aa62fca","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Que signifie la présence de règles régulières concernant le fonctionnement de l'axe et des voies génitales ?","a":"<div class=\"notion-course\"><p>La présence de règles régulières signe le <strong>bon fonctionnement de l'axe hypothalamo-hypophyso-ovarien</strong> et l'<strong>intégrité des voies génitales</strong>.</p></div>"},{"i":"58c8412c6391","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelle est la définition des métrorragies et la première démarche diagnostique à adopter chez une femme en âge de procréer ?","a":"<div class=\"notion-course\"><p>Les métrorragies sont des saignements d'origine utérine survenant en dehors des règles.</p><p>Chez une femme en âge de procréer, <strong>toute métrorragie impose d'éliminer en premier lieu une grossesse</strong> (dosage des <strong>β-hCG plasmatiques</strong>), et de ne pas méconnaître une <strong>grossesse extra-utérine (GEU)</strong> tant que la grossesse n'a pas été localisée par échographie.</p></div>"},{"i":"7f57638d8150","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les causes iatrogènes ou liées à la contraception pouvant entraîner des métrorragies ?","a":"<div class=\"notion-course\"><ul><li><strong>Contraception œstro-progestative (COP) mal observée</strong> ou en début de plaquette, oublis</li><li><strong>Microprogestatifs</strong>, implant à l'étonogestrel, <span class=\"nc-pink_bg\">DIU au lévonorgestrel</span> (spottings fréquents les 1ers mois)</li><li>DIU au cuivre (<span class=\"nc-blue_bg\">règles plus abondantes</span> ± spottings)</li><li>Contraception d'urgence</li><li>Traitement hormonal substitutif de la ménopause (THM) mal équilibré</li></ul></div>"},{"i":"9e19d1a2d1e5","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les étiologies 'liées à une grossesse' de métrorragies chez la femme en âge de procréer ?","a":"<div class=\"notion-course\"><ul><li><strong>Grossesse extra-utérine (GEU) +++</strong></li><li>Fausse couche spontanée</li><li>Môle hydatiforme</li><li><span class=\"nc-brown_bg\">Grossesse</span> intra-utérine évolutive avec <strong>hémorragie de Hartmann</strong> (J20-J25)</li><li>Pathologies du 2ème-3ème trimestre : <strong>placenta prævia</strong>, <strong>hématome rétroplacentaire</strong></li></ul></div>"},{"i":"ba9a634b00ba","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelle est la conduite à tenir face à une métrorragie post-ménopausique ?","a":"<div class=\"notion-course\"><p>Toute métrorragie post-ménopausique doit faire considérer un <strong>cancer de l'endomètre jusqu'à preuve du contraire</strong>.</p><p>Le bilan obligatoire comprend une <strong><span class=\"nc-blue_bg\">échographie pelvienne</span> endovaginale</strong> et une <strong>hystéroscopie</strong> (avec ou sans biopsie endométriale).</p></div>"},{"i":"d2f458ce6f8f","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les principales causes organiques de métrorragies chez la femme en âge de procréer ?","a":"<div class=\"notion-course\"><ul><li><strong>Polypes endométriaux ou cervicaux</strong></li><li><strong>Fibromes utérins</strong> (surtout sous-muqueux)</li><li><strong>Adénomyose</strong></li><li>Endométrite aiguë/chronique, cervicite, IGH</li><li><strong>Cancer du col utérin</strong> (+ chez la femme jeune avec métrorragies provoquées post-coïtales)</li><li>Cancer de l'endomètre (plus rare avant 40 ans)</li></ul></div>"},{"i":"1ec38991bc73","n":35,"o":"35-2","u":"Physiopathologie","t":"Connaître la physiopathologie du syndrome prémenstruel","q":"Que retenir concernant la physiopathologie du syndrome prémenstruel ?","a":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> du SPM est <em>mal connue</em>. L'<span><span class=\"nc-yellow_bg\">hyperœstrogénie relative</span></span><span class=\"nc-yellow_bg\"> (et parfois même </span><strong><span class=\"nc-yellow_bg\">absolue</span></strong><span class=\"nc-yellow_bg\">)</span> serait l'élément fondateur, induisant <span <span=\"\">&gt;2</span> grands mécanismes :</p>\n\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Conséquences cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Hyperperméabilité capillaire</span></strong></td>\n            <td>\n              <span>Œdème tissulaire interstitiel</span> dans certains organes :<br>\n              <strong>Seins</strong> : <span><span class=\"nc-yellow_bg\">mastodynies</span></span> ;<br>\n              <strong>Cerveau</strong> : <span><span class=\"nc-blue_bg\">céphalées</span></span>, manifestations neuropsychologiques ;<br>\n              <strong>Viscères abdomino-pelviens</strong> : <span>congestion pelvienne</span>, <span>troubles du transit</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Perturbations de la transmission sérotoninergique</span></strong></td>\n            <td>Participe à la survenue des <span><span class=\"nc-blue_bg\">troubles neuropsychologiques</span></span> (<span class=\"nc-blue_bg\">irritabilité</span>, <span class=\"nc-blue_bg\">syndrome dépressif</span>, <span class=\"nc-red nc-bold\">trouble dysphorique prémenstruel</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> C'est la rationalité du recours aux <span><span class=\"nc-pink nc-bold\">ISRS</span></span> dans les formes neuropsychologiques (effet sur la sérotonine) et aux <span>progestatifs/œstroprogestatifs</span> dans les formes globales (<span>réduction</span> du climat d'hyperœstrogénie relative).\n      </div></div>"},{"i":"aed581c39e23","n":35,"o":"35-3","u":"Étiologies","t":"Connaître les situations physiologiques ou pathologiques pouvant favoriser la survenue ou l’aggravation d’un syndrome prémenstruel","q":"Que retenir concernant les situations physiologiques ou pathologiques pouvant favoriser la survenue ou l’aggravation d’un syndrome prémenstruel ?","a":"<div class=\"notion-course\"><h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Facteurs favorisants</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitements hormonaux</strong></td>\n            <td>\n              <span><span class=\"nc-pink_bg\">Contraceptifs microprogestatifs</span></span> (voie orale ou implant SC) ;<br>\n              <span><span class=\"nc-pink_bg\">DIU au lévonorgestrel</span></span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Consommations excessives</strong> (mode de vie)</td>\n            <td>\n              <span><span class=\"nc-red nc-bold\">Caféine</span></span>, <span><span class=\"nc-red nc-bold\">nicotine</span></span>, <span><span class=\"nc-red nc-bold\">alcool</span></span>, <span><span class=\"nc-red nc-bold\">sucres rapides</span></span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étapes de la vie génitale où le SPM est plus fréquent</h4>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adolescence</strong></td>\n            <td>Les <em>1ers cycles</em> sont volontiers <span>dysovulatoires</span> → peut favoriser une <strong>hyperœstrogénie relative</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ phase de la périménopause +++</strong></td>\n            <td>\n              Tableau d'<span>« hyperstimulation endogène » des ovaires</span> associant :<br>\n              <strong><span class=\"nc-blue_bg\">Raccourcissement des cycles</span></strong> ;<br>\n              <strong><span class=\"nc-blue_bg\">Règles plus abondantes</span></strong>, voire hémorragiques chez certaines patientes ;<br>\n              <strong><span class=\"nc-blue_bg\">Climat d'hyperœstrogénie relative</span></strong><span class=\"nc-blue_bg\"> et même parfois </span><span><span class=\"nc-blue_bg\">absolue</span></span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div>"},{"i":"eb5add022df3","n":35,"o":"35-5","u":"Suivi et/ou pronostic","t":"Connaître les conséquences cliniques des troubles du cycle","q":"Que retenir concernant les conséquences cliniques des troubles du cycle ?","a":"<div class=\"notion-course\"><p>Les conséquences cliniques varient selon le type de trouble et son ancienneté. Plusieurs grands axes sont à retenir :</p>\n\n      <table>\n        <thead><tr><th>Axe</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Gêne fonctionnelle</strong></td>\n            <td>\n              <span>Inconfort cyclique</span> (<span class=\"nc-yellow_bg\">mastodynies</span>, ballonnement, <span class=\"nc-blue_bg\">irritabilité</span> — cf SPM) ;<br>\n              <span>Retentissement sur la qualité de vie</span>, professionnel, relationnel ;<br>\n              <strong><span class=\"nc-red nc-bold\">Trouble dysphorique prémenstruel</span></strong> (DSM-5) dans les formes psychiatriques sévères.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fertilité</strong></td>\n            <td>\n              <span>Hypofertilité / infertilité</span> en cas d'anovulation chronique (SOPK, insuffisance ovarienne prématurée, hyperprolactinémie) — motif fréquent de consultation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endomètre</strong></td>\n            <td>\n              <span>Hyperplasie endométriale</span> en cas d'imprégnation œstrogénique non opposée par la progestérone (anovulation prolongée) — risque à terme de <strong>cancer de l'endomètre</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragies</strong></td>\n            <td><span>Ménorragies</span> sévères pouvant entraîner une <span>anémie ferriprive</span> ; spottings désagréables.</td>\n          </tr>\n          <tr>\n            <td><strong>Osseux et cardio-vasculaire</strong></td>\n            <td>Carence œstrogénique prolongée (IOP, aménorrhée hypothalamique sévère) → <span>perte de densité osseuse</span> ± retentissement <span>CV</span> à long terme.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Note de source.</strong> Le Collège CNGOF (5ᵉ éd., 2021) ne consacre pas de section spécifique à cet objectif transversal. La synthèse ci-dessus consolide les conséquences mentionnées au fil des chapitres aménorrhée/IOP (carence œstrogénique → risque osseux) et hémorragies (ménorragies → anémie ferriprive ; anovulation prolongée → hyperplasie endométriale).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 42 — Aménorrhée</em></p></div>"},{"i":"3a51acaa39dc","n":35,"o":"35-7","u":"Étiologies","t":"Connaître les principales causes de ménorragies","q":"Que retenir concernant les principales causes de ménorragies ?","a":"<div class=\"notion-course\"><p>Les <span>ménorragies</span> = règles <strong>anormalement abondantes</strong> (&gt; <span>80 mL</span>) et/ou <strong>prolongées</strong> (&gt; <span>7 jours</span>). Quand elles s'associent à des saignements inter-menstruels, on parle de <span>méno-métrorragies</span>. La quantification objective repose sur le <span>score de Higham</span> : on parle de ménorragies pour un <span>score</span> <span>&gt; 100</span>. La démarche distingue <span <span=\"\">&gt;3</span> grands cadres :</p>\n\n      <table>\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Organiques utérines</strong></td>\n            <td>\n              <span>Fibromes utérins</span> +++ (surtout <strong>sous-muqueux</strong> et <strong>interstitiels</strong>) ;<br>\n              <span>Adénomyose</span> ;<br>\n              <span>Polypes endométriaux</span> ;<br>\n              <span>Hyperplasie endométriale</span> ± atypique ;<br>\n              <span>Cancer de l'endomètre</span> ;<br>\n              <span>Malformations utérines</span> ; <span>cicatrice de césarienne</span> (isthmocèle).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnelles</strong></td>\n            <td>\n              <span>Dysovulation / anovulation</span> chronique → endomètre proliféré non opposé par la progestérone ;<br>\n              Particulièrement fréquent en <strong>péri-ménarche</strong> et en <strong>périménopause</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Trouble de l'hémostase</strong></td>\n            <td>\n              <span>Maladie de Willebrand</span> +++ (à évoquer chez l'<strong>adolescente</strong> avec ménorragies dès la ménarche) ;<br>\n              <span>Thrombopénies</span> (PTI, hémopathies) ;<br>\n              <span>Traitements anticoagulants</span> / <span>antiagrégants</span> ;<br>\n              <span>Insuffisance hépatique</span> sévère, coagulopathies de consommation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes contraception</strong></td>\n            <td>\n              <span>DIU au cuivre</span> : majore l'abondance et la durée des règles ;<br>\n              <span>Microprogestatifs</span> à l'inverse : peuvent provoquer spottings/aménorrhée plutôt que ménorragies.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes</strong></td>\n            <td>\n              <span>Hypothyroïdie</span> (peut majorer les ménorragies) ;<br>\n              <span>SOPK</span> (rare ménorragie pure — plus souvent spaniomé/aménorrhée puis hémorragies de privation abondantes).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — réflexe.</strong> Une adolescente avec ménorragies sévères dès la ménarche → <span>évoquer un trouble de l'hémostase</span> (maladie de Willebrand surtout) en plus du bilan habituel (β-hCG, <span>NFS</span>, <span>échographie</span>).\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitements généraux (quelle que soit l'étiologie).</strong> Selon le Collège CNGOF :\n        <ul>\n          <li><span>Antifibrinolytique</span> : acide tranexamique (Exacyl®) ;</li>\n          <li><span>Traitement martial</span> per os ou IV ;</li>\n          <li><strong>Transfusion</strong> si besoin.</li>\n        </ul>\n        Puis traitement <strong>étiologique</strong> : polype (résection hystéroscopique), adénomyose et myome (DIU au lévonorgestrel en 1ʳᵉ intention, <span>chirurgie</span> sinon), hyperplasie sans atypie (progestatifs PO ou DIU LNG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin · 41 — Endométrisose · 36 — Contraception</em></p></div>"},{"i":"cea879b962b2","n":35,"o":"35-8","u":"Étiologies","t":"Connaître les principales étiologies d’aménorrhée primaire","q":"Que retenir concernant les principales étiologies d’aménorrhée primaire ?","a":"<div class=\"notion-course\"><p><span>Aménorrhée primaire</span> = absence de ménarche après <span>15 ans</span> en présence d'un développement pubertaire normal, ou à <span>13 ans</span> en l'absence de tout signe de puberté. La démarche s'organise <strong>selon la présence ou non d'un développement pubertaire</strong> et selon les anomalies utéro-vaginales associées.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe Collège — 2 diagnostics en cas d'absence d'utérus à l'<span>échographie</span>.</strong> Bien différencier :\n        <ul>\n          <li><span>Agénésie müllérienne (MRKH)</span> : aplasie <span>congénitale</span> de l'utérus et des 2/3 supérieurs du vagin, caryotype <strong>46,XX</strong>, caractères sexuels secondaires normaux ;</li>\n          <li><span>Insensibilité complète aux androgènes (Morris)</span> : caryotype <strong>46,XY</strong>, phénotype féminin, testicules intra-abdominaux/inguinaux — <em>cause exceptionnelle</em>.</li>\n        </ul>\n      </div>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies anatomiques</strong> (filière génitale)</td>\n            <td>\n              <span>Imperforation hyménale</span> (hématocolpos, douleurs cycliques) ;<br>\n              <span>Malformations müllériennes</span> : agénésie / hypoplasie utérine, cloisons vaginales transverses ;<br>\n              <span>Syndrome de Mayer-Rokitansky-Küster-Hauser (MRKH)</span> : agénésie utéro-vaginale, ovaires fonctionnels, caryotype 46,XX ;<br>\n              <span>Syndrome d'insensibilité aux androgènes (Morris)</span> : phénotype féminin, caryotype 46,XY, testicules ectopiques.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anomalies chromosomiques / dysgénésies gonadiques</strong></td>\n            <td>\n              <span>Syndrome de Turner</span> (45,X et mosaïques) +++ : petite taille, dysgénésie gonadique, impubérisme, FSH élevée ;<br>\n              Dysgénésies gonadiques pures 46,XX ou 46,XY (<span>syndrome de Swyer</span>) ;<br>\n              Trisomies, anomalies du chromosome X.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypogonadisme hypogonadotrope</strong> (cause centrale)</td>\n            <td>\n              <span>Retard pubertaire constitutionnel</span> (diagnostic d'élimination) ;<br>\n              <span>Syndrome de Kallmann</span> (déficit GnRH + anosmie) ;<br>\n              <span>Hyperprolactinémie</span> (adénome hypophysaire, médicamenteuse) ;<br>\n              Pathologies hypothalamo-hypophysaires (craniopharyngiome, tumeurs sellaires, <span>irradiation</span>) ;<br>\n              <span>Anorexie mentale</span>, dénutrition sévère, activité physique intense.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies endocriniennes / chroniques</strong></td>\n            <td>\n              <span>Hypothyroïdie</span> sévère ;<br>\n              <span>Hyperplasie congénitale des surrénales</span> (bloc en 21-hydroxylase) ;<br>\n              Maladies chroniques sévères (<span>MICI</span>, <span>insuffisance rénale</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire</em></p></div>"},{"i":"e0b536399f18","n":35,"o":"35-9","u":"Étiologies","t":"Connaître les principales étiologies d’aménorrhée secondaire","q":"Que retenir concernant les principales étiologies d’aménorrhée secondaire ?","a":"<div class=\"notion-course\"><p><span>Aménorrhée secondaire</span> = arrêt des règles <span>≥ 3 mois consécutifs</span> chez une femme antérieurement réglée. La démarche étiologique s'appuie sur l'<strong>algorithme du <span class=\"nc-blue_bg\">bilan hormonal</span></strong> (cf obj-10) qui classe les causes en <strong>3 cadres</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Réflexe 1ᵉʳ.</strong> Avant tout bilan, <span>éliminer une <span class=\"nc-brown_bg\">grossesse</span></span> — la 1ʳᵉ cause d'aménorrhée secondaire chez une femme en âge de procréer reste la <span><span class=\"nc-brown_bg\">grossesse</span></span>. <span>β-hCG plasmatique</span> systématique.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 1 — FSH/LH/œstradiol bas → cause centrale (hypothalamo-hypophysaire)</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hyperprolactinémie</strong> (prolactine ↑)</td>\n            <td>\n              <span>Adénome hypophysaire à prolactine (prolactinome)</span> +++ ;<br>\n              <strong>Hyperprolactinémie médicamenteuse</strong> (<span>neuroleptiques</span>, antiémétiques, antidépresseurs, <span>opiacés</span>) ;<br>\n              <span>Hypothyroïdie</span> périphérique (TRH ↑ → PRL ↑) ; <span>insuffisance rénale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres causes centrales</strong> (prolactine normale)</td>\n            <td>\n              <span>Aménorrhée hypothalamique fonctionnelle</span> : <span>anorexie mentale</span>, dénutrition, sport intensif, stress chronique ;<br>\n              <span>Syndrome de Sheehan</span> (<span>nécrose</span> hypophysaire du post-partum <span>hémorragique</span>) ;<br>\n              <span>Craniopharyngiome</span>, tumeurs sellaires, hypophysite, séquelles d'<span>irradiation</span>/<span>chirurgie</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 2 — FSH/(LH)/œstradiol normaux → cause utéro-vaginale ou SOPK</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>SOPK</strong> (syndrome des ovaires polykystiques) +++</td>\n            <td><span>5 à 10 %</span> des femmes en âge de procréer. <em>Cause la plus fréquente d'anovulation et d'aménorrhée secondaire normo-œstrogénique</em> ; test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> positif. <strong><span>Critères de</span> Rotterdam</strong> (2/3 suffisent, après exclusion des autres causes) : oligo/anovulation ; hyperandrogénie clinique/bio ; aspect échographique d'<span>ovaires polymicrokystiques</span> (<span>≥ 12 follicules de 2-9 mm</span> par ovaire et/ou volume ovarien <span>&gt; 10 mL</span>). Doser la <span>17-OH-progestérone</span> pour éliminer un bloc en 21-hydroxylase ; <span>AMH</span> élevée.</td>\n          </tr>\n          <tr>\n            <td><strong>Causes utéro-vaginales acquises</strong></td>\n            <td>\n              <span>Synéchies utérines</span> (syndrome d'Asherman) — post-<span>curetage</span>, post-endométrite ;<br>\n              Sténoses cervicales post-conisation, post-chirurgicales.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 3 — FSH/(LH) élevées + œstradiol bas → insuffisance ovarienne</h4>\n      <table>\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Insuffisance ovarienne prématurée (IOP)</strong></td>\n            <td>\n              <span>Aménorrhée &gt; 4 mois avant 40 ans + FSH &gt; 25 UI/l</span> (sur 2 dosages) + signes d'hypo-œstrogénie. Hypogonadisme <strong>hypergonadotrope</strong> ; ne répond pas au <span class=\"nc-yellow_bg\">test aux progestatifs</span>. Concerne <span>1 % des femmes &lt; 40 ans</span> (<span>0,1 %</span> avant <span>30 ans</span>). Étiologies : <em>idiopathique dans <span>80 %</span> des cas</em>, génétiques (Turner, prémutation X fragile FMR1, polyendocrinopathies), <span>iatrogène</span> (chimio, <span>radiothérapie</span>, <span>chirurgie</span> ovarienne), <span>auto-immune</span> (Addison). Faire caryotype + recherche prémutation FMR1 + bilan auto-immun.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ménopause</strong></td>\n            <td>Aménorrhée &gt;<span> 12 mois</span> chez une femme &gt;<span> 45-50 ans</span> en moyenne, avec FSH élevée et symptômes climatériques.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 253 — <span>Obésité</span> · 38 — Infertilité du couple</em></p></div>"},{"i":"8587e2121512","n":35,"o":"35-10","u":"Étiologies","t":"Connaître les principales étiologies de spanioménorrhée","q":"Que retenir concernant les principales étiologies de spanioménorrhée ?","a":"<div class=\"notion-course\"><p>La <span>spanioménorrhée</span> = cycles <span>&gt; 35 jours</span> (souvent &gt; 45 j = oligospanioménorrhée), c'est-à-dire des règles <strong>espacées et peu fréquentes</strong>. Elle correspond souvent à une <strong>forme fruste</strong> des étiologies d'aménorrhée secondaire — l'ovulation est irrégulière mais non totalement absente.</p>\n\n      <table>\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Endocrino-ovariennes</strong></td>\n            <td>\n              <span>SOPK</span> +++ — <em>cause de loin la plus fréquente</em>, sur <span>terrain</span> d'hyperandrogénie ± insulinorésistance ;<br>\n              <span>Insuffisance ovarienne débutante</span> (forme infraclinique précoce de l'IOP) ;<br>\n              <span>Périménopause</span> : raccourcissement puis allongement progressif des cycles avant aménorrhée définitive.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypothalamo-hypophysaires</strong></td>\n            <td>\n              <span>Hyperprolactinémie modérée</span> (médicamenteuse, microadénome) ;<br>\n              <span>Aménorrhée hypothalamique fonctionnelle</span> dans ses formes débutantes : <span>anorexie</span> / dénutrition modérée, sport intensif, stress chronique.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes générales</strong></td>\n            <td>\n              <span>Dysthyroïdies</span> (hypo- comme <span>hyperthyroïdie</span>) ;<br>\n              <span>Hyperplasie congénitale des surrénales</span> à révélation tardive ;<br>\n              <span>Hypercorticisme</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métaboliques</strong></td>\n            <td><span>Obésité</span> sévère (lien avec SOPK), <em>très bas poids</em> / dénutrition.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant une spanioménorrhée chez une femme jeune, le <span>SOPK</span> est l'hypothèse à éliminer en 1ʳᵉ intention (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> + <span class=\"nc-blue_bg\">bilan hormonal</span> + testostérone totale + SHBG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 253 — <span>Obésité</span> · 38 — Infertilité du couple</em></p></div>"},{"i":"1d33182fe046","n":35,"o":"35-11","u":"Examens complémentaires","t":"Connaître le bilan à réaliser pour le diagnostic des aménorrhées et des troubles du cycle","q":"Que retenir concernant le bilan à réaliser pour le diagnostic des aménorrhées et des troubles du cycle ?","a":"<div class=\"notion-course\"><p>Le bilan d'une aménorrhée ou d'un trouble du cycle s'articule en 3 temps : <strong>1ʳᵉ intention</strong> (test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span>), <strong><span class=\"nc-blue_bg\">bilan hormonal</span></strong> et <strong>imagerie</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Préalable systématique.</strong> <span>β-hCG plasmatique</span> avant toute exploration — <span>éliminer une <span class=\"nc-brown_bg\">grossesse</span></span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Orientation à l'examen clinique (CAT Collège).</strong> Avant les dosages, rechercher :\n        <ul>\n          <li><span>Signes d'hyperandrogénie</span> : hirsutisme (<span>score de Ferriman-Galwey &gt; 6</span>), acné sévère, alopécie androgénique du vertex → oriente vers un <span>SOPK</span> ;</li>\n          <li><span>Galactorrhée</span> : association aménorrhée-galactorrhée très évocatrice d'<span>hyperprolactinémie</span> ;</li>\n          <li><span>Signes de carence œstrogénique</span> : bouffées vasomotrices, sécheresse vaginale, dyspareunie, troubles du sommeil/psychiques, perte de libido ;</li>\n          <li><strong>Poids / IMC / fluctuations pondérales</strong>, <span>TCA</span>, érythrocyanose des extrémités + lanugo (signes d'hypométabolisme) → <span>aménorrhée hypothalamique fonctionnelle</span>.</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1ʳᵉ intention — <span class=\"nc-yellow_bg\">test aux progestatifs</span> (<span class=\"nc-pink nc-bold\">dydrogestérone</span>)</h4>\n      <p>1ᵉʳ test à réaliser devant toute aménorrhée <strong>secondaire</strong>, dans le but de déclencher une <em>hémorragie de privation</em>. Apport diagnostique limité (FP/FN importants), mais il oriente la suite du bilan.</p>\n\n      <table>\n        <thead><tr><th>Paramètre</th><th>Résultat / interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>Administration d'un <span><span class=\"nc-pink_bg\">progestatif</span></span> (généralement <span><span class=\"nc-pink nc-bold\">dydrogestérone</span></span>) <em>per os</em>, <span>10 à 20 mg/j pendant <span class=\"nc-pink nc-bold\">7-10 jours</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Test positif</strong></td>\n            <td>\n              <strong>Définition</strong> : survenue des <span class=\"nc-green_bg\">menstruations dans les </span><span><span class=\"nc-green_bg\">5 jours</span></span><span class=\"nc-green_bg\"> suivant l'arrêt</span> du <span class=\"nc-pink_bg\">progestatif</span> ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>imprégnation œstrogénique de l'endomètre suffisante</strong> ;<br>\n              Si aménorrhée + test positif = <span>aménorrhée par anovulation normo-œstrogénique</span> (ex. <span>SOPK</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Test négatif</strong></td>\n            <td>\n              <strong>Définition</strong> : <span class=\"nc-red_bg\">absence d'hémorragie</span> de privation ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>carence œstrogénique</strong> (pas de croissance endométriale). Causes :<br>\n              <span><span class=\"nc-orange_bg\">Hypofonctionnement ovarien sévère</span></span> (atrophie endométriale par hypo-œstrogénie, indépendamment de sa cause) ;<br>\n              <span><span class=\"nc-orange_bg\">Anomalie anatomique de la filière génitale</span></span> ;<br>\n              <strong><span><span class=\"nc-brown_bg\">Grossesse</span></span></strong> (malgré l'imprégnation œstrogénique, la progestérone endogène est maintenue → pas d'hémorragie de privation).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Suites diagnostiques</strong></td>\n            <td>\n              <span class=\"nc-blue_bg\">Bilan hormonal</span> + <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> :<br>\n              Si test <strong>positif</strong> : examens complémentaires <span><span class=\"nc-pink nc-bold\">3 jours</span></span><span class=\"nc-pink nc-bold\"> après</span> le cycle déclenché ;<br>\n              Si test <strong>négatif</strong> (ou absence de test) : examens complémentaires peuvent être réalisés en aménorrhée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Limite du test.</strong> Il n'est qu'une <em>indication diagnostique</em> — taux de <span>faux positifs et faux négatifs important</span>. Ne dispense jamais d'un <span class=\"nc-blue_bg\">bilan hormonal</span> complet.\n      </div>\n\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"nc-blue_bg\">Bilan hormonal</span> — au moment des règles (<span>J2</span>-J5)</h4>\n      <p>Dosages : <span>β-hCG</span>, <span>FSH</span>, <span>œstradiol</span>, <span>prolactine</span> ± <span>LH</span>. Bilan à réaliser au moment des règles (<span>J2-J5 du cycle</span>) pour être interprété correctement, donc :</p>\n      <ul>\n        <li>Soit <strong>directement</strong> si le test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> est négatif ;</li>\n        <li>Soit <span><span class=\"nc-pink nc-bold\">3 jours après</span></span> un test à la <span class=\"nc-pink nc-bold\">dydrogestérone</span> positif.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique du <span class=\"nc-blue_bg\">bilan hormonal</span> (algorithme Collège)</h4>\n      <table>\n        <thead><tr><th>Profil hormonal</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FSH, LH, œstradiol bas</strong></td>\n            <td>\n              <span>Cause centrale</span> :<br>\n              <strong>Prolactine élevée</strong> → <span>hyperprolactinémie</span> (prolactinome, médicamenteuse) ;<br>\n              <strong>Prolactine normale</strong> → <span>autres causes centrales</span> (aménorrhée hypothalamique fonctionnelle, Sheehan, craniopharyngiome).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH), œstradiol normaux</strong></td>\n            <td>\n              <span>Cause utéro-vaginale</span> ou <span>SOPK</span> ;<br>\n              <strong>Apport de l'<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> +++</strong> (ovaires polykystiques, synéchies, anomalie filière).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH) élevées + œstradiol bas</strong></td>\n            <td><span>Insuffisance ovarienne prématurée</span> (avant <span>40 ans</span>) ou ménopause physiologique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie</h4>\n      <p><span><span class=\"nc-blue_bg\">Échographie pelvienne</span></span> (sus-pubienne ± endovaginale) — recherche :</p>\n      <ul>\n        <li><strong>Anomalie de la filière génitale</strong> : agénésie utérine, synéchies, malformations müllériennes ;</li>\n        <li><strong>Pathologie ovarienne</strong> : aspect d'<span>ovaires polykystiques</span>, kystes, atrophie ovarienne (IOP).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>En 2ᵈ intention</strong> selon l'orientation : <span>IRM hypophysaire</span> (si hyperprolactinémie ou suspicion centrale), <span>caryotype</span> (Turner, dysgénésies), bilan <span>auto-immun</span> (IOP), <span>testostérone totale + SHBG</span> (SOPK, hyperandrogénie), <span>TSH</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 38 — Infertilité du couple</em></p></div>"},{"i":"58ca4cba56aa","n":35,"o":"35-13","u":"Identifier une urgence","t":"Reconnaître les situations d’urgence en cas de saignements utérins","q":"Que retenir concernant reconnaître les situations d’urgence en cas de saignements utérins ?","a":"<div class=\"notion-course\"><p>Plusieurs scénarios imposent une <strong>prise en charge urgente</strong> devant des saignements utérins. À reconnaître au moindre signe d'appel.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Savoir évaluer les pertes sanguines &amp; la gravité</h4>\n      <table>\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Quantification</strong></td>\n            <td>Interrogatoire (garnitures, caillots, vêtements tachés), <span>score de Higham</span> (&gt; 100 = ménorragies), spéculum (saignement actif ?), <span>HemoCue® / NFS</span> (taux d'<span>hémoglobine</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Anémie mal tolérée</strong></td>\n            <td><span>Tachycardie</span>, <span>pâleur</span> cutanéo-muqueuse et conjonctivale, <span>dyspnée</span>, <span>asthénie</span>, <span>vertiges</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes de <span>choc</span></strong></td>\n            <td><span>Hypotension</span>, <span>malaise</span>, <span>sueurs</span>, extrémités froides, marbrures.</td>\n          </tr>\n          <tr>\n            <td><strong>Mise en condition</strong> (si <span>choc</span> / anémie mal tolérée)</td>\n            <td><span>Hospitalisation</span>, <span>2 VVP de bon calibre</span>, réchauffement, <span>oxygénothérapie</span>, bilan bio (<span>NFS</span>, hémostase, groupe + rhésus 2 déterminations, bilan prétransfusionnel, β-hCG sauf <span>grossesse</span> IU connue).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>1. <span>Grossesse</span> extra-utérine (GEU) rompue.</strong>\n        <ul>\n          <li><span>Femme en âge de procréer</span> + <span>métrorragies</span> ± <span>douleur pelvienne brutale</span> + <span>retard de règles</span> ;</li>\n          <li>Signes péritonéaux, hémopéritoine, scapulalgie (irritation phrénique) ;</li>\n          <li><span>Choc hémorragique</span> possible — collapsus, <span>tachycardie</span>, <span>pâleur</span> ;</li>\n          <li><strong>CAT</strong> : <span>β-hCG urgente</span> + <span><span class=\"nc-blue_bg\">échographie pelvienne</span> endovaginale</span> + <strong>bloc</strong> (cœlioscopie d'<span>urgence</span>).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>2. Hémorragie sévère / <span>choc</span> <span>hémorragique</span> (toutes causes).</strong>\n        <ul>\n          <li><span>Tachycardie</span>, <span>hypotension artérielle</span>, <span>pâleur</span>, marbrures, <span>sueurs</span>, troubles de la conscience ;</li>\n          <li>Saignement extériorisé abondant et persistant ;</li>\n          <li><strong>CAT</strong> : 2 VVP de gros calibre, <span>groupe-Rh-RAI + NFS + hémostase</span> en <span>urgence</span>, <strong>remplissage</strong> par cristalloïdes, <strong>transfusion</strong> de CGR ± PFC/<span>plaquettes</span> si critères, geste d'<strong>hémostase</strong> (utérotoniques, tamponnement, embolisation, <span>chirurgie</span> selon contexte).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>3. Contexte du post-partum — hémorragie de la délivrance / atonie utérine.</strong>\n        <ul>\n          <li>Saignement &gt; <span>500 mL</span> (voie basse) / <span>1000 mL</span> (césarienne) dans les <span>24h</span> ;</li>\n          <li><span>Globe utérin de sécurité absent</span>, utérus mou ;</li>\n          <li><strong>CAT</strong> : révision utérine, massage, <span>oxytocine</span> puis <span>sulprostone</span>, embolisation/<span>chirurgie</span> d'hémostase si échec.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>4. Drapeaux diagnostiques à ne pas manquer (semi-urgents).</strong>\n        <ul>\n          <li><span>Toute métrorragie post-ménopausique</span> = cancer de l'endomètre jusqu'à preuve du contraire — exploration en consultation rapide (<span>échographie</span> + hystéroscopie/<span>biopsie</span>) ;</li>\n          <li><span>Métrorragies provoquées post-coïtales chez la femme jeune</span> → cancer du col utérin à éliminer (examen au spéculum, FCV, <span>biopsie</span> cervicale dirigée si <span>lésion</span>) ;</li>\n          <li><span>Anémie chronique mal tolérée</span> (<span>asthénie</span> majeure, <span>dyspnée</span>, <span>angor</span>) sur ménorragies prolongées.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine · 24 — Complications de la grossesse</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941816088a4f88f09a63e87?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Menorragies202022-RPC.pdf","label":"CNGOF · Ménorragies, 2022"}]};
